<?php
defined('ABSPATH') || exit;
function somsa_sms_install(){global $wpdb;require_once ABSPATH.'wp-admin/includes/upgrade.php';$charset=$wpdb->get_charset_collate();$q=$wpdb->prefix.'somsa_sms';$n=$wpdb->prefix.'somsa_sms_notifications';dbDelta("CREATE TABLE $q (
 id bigint(20) unsigned NOT NULL AUTO_INCREMENT,
 booking_id bigint(20) unsigned NOT NULL,
 due_at datetime NOT NULL,
 status varchar(20) NOT NULL DEFAULT 'queued',
 attempts smallint NOT NULL DEFAULT 0,
 provider_id varchar(64) DEFAULT NULL,
 last_error varchar(200) DEFAULT NULL,
 updated_at datetime NOT NULL,
 PRIMARY KEY  (id), UNIQUE KEY booking_id (booking_id), KEY due_status (status,due_at)
 ) $charset;");dbDelta("CREATE TABLE $n (
 id bigint(20) unsigned NOT NULL AUTO_INCREMENT,
 booking_id bigint(20) unsigned NOT NULL,
 event_type varchar(32) NOT NULL,
 due_at datetime NOT NULL,
 status varchar(20) NOT NULL DEFAULT 'queued',
 attempts smallint NOT NULL DEFAULT 0,
 provider_id varchar(64) DEFAULT NULL,
 last_error varchar(200) DEFAULT NULL,
 updated_at datetime NOT NULL,
 PRIMARY KEY  (id), UNIQUE KEY booking_event (booking_id,event_type), KEY due_status (status,due_at)
 ) $charset;");update_option('somsa_sms_version','2');}
add_filter('cron_schedules',function($s){$s['somsa_five_minutes']=['interval'=>300,'display'=>'SOMA: every five minutes'];return $s;});
add_action('init',function(){if(get_option('somsa_sms_version')!=='2')somsa_sms_install();if(!wp_next_scheduled('somsa_sms_worker'))wp_schedule_event(time()+60,'somsa_five_minutes','somsa_sms_worker');});
add_action('switch_theme',function(){wp_clear_scheduled_hook('somsa_sms_worker');});
function somsa_sms_configured(){return get_option('somsa_sms_enabled','0')==='1'&&get_option('somsa_sms_provider','')==='melipayamak'&&trim((string)get_option('somsa_sms_username',''))!==''&&trim((string)get_option('somsa_sms_password',''))!==''&&preg_match('/^[0-9+]{3,20}$/',(string)get_option('somsa_sms_sender',''));}
function somsa_sms_slot_timestamp($slot){return (new DateTimeImmutable($slot,wp_timezone()))->getTimestamp();}
function somsa_sms_active_statuses(){return ['paid','vip_request','signature_request'];}
function somsa_sms_sync(){global $wpdb;$queue=$wpdb->prefix.'somsa_sms';$bookings=$wpdb->prefix.'somsa_bookings';$hours=max(1,min(72,(int)get_option('somsa_sms_hours',3)));$now=gmdate('Y-m-d H:i:s');$statuses=somsa_sms_active_statuses();$in="'".implode("','",array_map('esc_sql',$statuses))."'";$rows=$wpdb->get_results("SELECT id,slot FROM $bookings WHERE status IN ($in) AND slot>'".esc_sql(current_time('mysql'))."'");foreach($rows as $r){$due=gmdate('Y-m-d H:i:s',max(time(),somsa_sms_slot_timestamp($r->slot)-$hours*HOUR_IN_SECONDS));$wpdb->query($wpdb->prepare("INSERT IGNORE INTO $queue (booking_id,due_at,status,updated_at) VALUES (%d,%s,'queued',%s)",$r->id,$due,$now));}$wpdb->query($wpdb->prepare("UPDATE $queue SET status='unknown',last_error='worker_interrupted',updated_at=%s WHERE status='sending' AND updated_at<%s",$now,gmdate('Y-m-d H:i:s',time()-600)));$wpdb->query($wpdb->prepare("UPDATE $queue q LEFT JOIN $bookings b ON b.id=q.booking_id SET q.status='cancelled',q.updated_at=%s WHERE q.status='queued' AND (b.id IS NULL OR b.status NOT IN ('paid','vip_request','signature_request') OR b.slot<=%s)",$now,current_time('mysql')));}
function somsa_sms_jalali_date($stamp){if(class_exists('IntlDateFormatter')){$f=new IntlDateFormatter('fa_IR@calendar=persian',IntlDateFormatter::NONE,IntlDateFormatter::NONE,wp_timezone()->getName(),IntlDateFormatter::TRADITIONAL,'yyyy/MM/dd');$v=$f->format($stamp);if($v!==false)return $v;}return wp_date('Y/m/d',$stamp);}
function somsa_sms_send_to($phone,$message){$base='https://rest.payamak-panel.com/api/SendSMS/SendSMS';$response=wp_remote_post($base,['timeout'=>25,'headers'=>['Accept'=>'application/json'],'body'=>['username'=>get_option('somsa_sms_username',''),'password'=>get_option('somsa_sms_password',''),'to'=>$phone,'from'=>get_option('somsa_sms_sender',''),'text'=>$message,'isflash'=>'false']]);if(is_wp_error($response))return ['state'=>'unknown','error'=>'connection_uncertain'];$http=wp_remote_retrieve_response_code($response);$body=json_decode(wp_remote_retrieve_body($response),true);if($http===200&&is_array($body)&&(int)($body['RetStatus']??$body['retStatus']??0)===1){$id=$body['Value']??$body['value']??'';return ['state'=>'sent','provider_id'=>sanitize_text_field((string)$id)];}return ['state'=>'failed','error'=>'provider_rejected_'.$http.'_'.(int)($body['RetStatus']??$body['retStatus']??0)];}
function somsa_sms_message($booking,$kind='preappointment'){$stamp=somsa_sms_slot_timestamp($booking->slot);$when=somsa_sms_jalali_date($stamp).' ساعت '.wp_date('H:i',$stamp,wp_timezone());$service=$booking->service_name?:'خدمت رزروشده';if($kind==='confirmation')return 'رزرو SOMA STUDIO ثبت شد: '.$when.'، خدمت: '.$service.'، بیعانه پرداخت‌شده: '.number_format_i18n((int)$booking->deposit).' تومان. منتظر دیدار شما هستیم.';if($kind==='request')return 'درخواست رزرو SOMA STUDIO دریافت شد: '.$when.'، خدمت: '.$service.'، بیعانه آنلاین ندارد. استودیو برای تأیید نهایی با شما هماهنگ می‌کند.';if($kind==='followup')return 'یک ماه از نوبت '.$service.' شما در SOMA STUDIO گذشته است. برای رزرو نوبت بعدی به somsastudio.ir مراجعه کنید.';return 'یادآوری نوبت SOMA STUDIO: '.$when.'، خدمت: '.$service.'. منتظر حضور شما هستیم.';}
function somsa_sms_queue_event($booking,$event,$recipient,$due){global $wpdb;$table=$wpdb->prefix.'somsa_sms_notifications';$utc=gmdate('Y-m-d H:i:s',$due);$wpdb->query($wpdb->prepare("INSERT IGNORE INTO $table (booking_id,event_type,due_at,status,updated_at) VALUES (%d,%s,%s,'queued',%s)",$booking->id,$event,$utc,gmdate('Y-m-d H:i:s')));}
function somsa_sms_booking_confirmed($bookingId){global $wpdb;$b=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}somsa_bookings WHERE id=%d",$bookingId));if(!$b)return;$now=time();$statuses=somsa_sms_active_statuses();if(!in_array($b->status,$statuses,true))return;$event=$b->status==='paid'?'confirmation':'request';somsa_sms_queue_event($b,$event,'customer',$now);if(trim((string)get_option('somsa_sms_owner_phone',''))!=='')somsa_sms_queue_event($b,'owner','owner',$now);$date=(new DateTimeImmutable($b->slot,wp_timezone()))->modify('+1 month')->getTimestamp();somsa_sms_queue_event($b,'followup','customer',$date);}
add_action('woocommerce_payment_complete','somsa_woo_booking_paid',20,1);add_action('woocommerce_order_status_processing','somsa_woo_booking_paid',20,1);add_action('woocommerce_order_status_completed','somsa_woo_booking_paid',20,1);
function somsa_woo_booking_paid($orderId){if(!function_exists('wc_get_order'))return;$order=wc_get_order($orderId);if(!$order)return;$bookingId=(int)$order->get_meta('_somsa_booking_id');if(!$bookingId)return;global $wpdb;$table=$wpdb->prefix.'somsa_bookings';$b=$wpdb->get_row($wpdb->prepare("SELECT * FROM $table WHERE id=%d",$bookingId));if(!$b||$b->status==='paid')return;$expired=$b->status==='expired';if($expired){$other=somsa_slot_is_available(substr($b->slot,0,10),substr($b->slot,11,5),(int)$b->duration);if(!$other){$wpdb->update($table,['status'=>'paid_review','active_slot'=>null,'ref_id'=>(string)$orderId],['id'=>$bookingId]);$order->add_order_note('پرداخت پس از پایان مهلت انجام شد و ساعت رزرو نیاز به هماهنگی یا بازپرداخت دارد.');return;}}$wpdb->update($table,['status'=>'paid','active_slot'=>$b->slot,'ref_id'=>(string)$orderId],['id'=>$bookingId]);$order->update_meta_data('_somsa_booking_paid','yes');$order->save();somsa_sms_booking_confirmed($bookingId);}
function somsa_sms_event_message($b,$event){if($event==='owner')return 'رزرو جدید SOMA STUDIO: '.$b->customer.'، '.$b->phone.'، '.somsa_sms_jalali_date(somsa_sms_slot_timestamp($b->slot)).' ساعت '.wp_date('H:i',somsa_sms_slot_timestamp($b->slot),wp_timezone()).'، '.$b->service_name.'، بیعانه: '.number_format_i18n((int)$b->deposit).' تومان.';return somsa_sms_message($b,$event);}
add_action('somsa_sms_worker','somsa_sms_worker');
function somsa_sms_worker(){if(!somsa_sms_configured())return;somsa_sms_sync();global $wpdb;$now=gmdate('Y-m-d H:i:s');$queue=$wpdb->prefix.'somsa_sms';$bookings=$wpdb->prefix.'somsa_bookings';$jobs=$wpdb->get_results($wpdb->prepare("SELECT * FROM $queue WHERE status='queued' AND due_at<=%s ORDER BY due_at LIMIT 20",$now));foreach($jobs as $job){$claimed=$wpdb->query($wpdb->prepare("UPDATE $queue SET status='sending',attempts=attempts+1,updated_at=%s WHERE id=%d AND status='queued'",$now,$job->id));if($claimed!==1)continue;$b=$wpdb->get_row($wpdb->prepare("SELECT * FROM $bookings WHERE id=%d",$job->booking_id));if(!$b||!in_array($b->status,somsa_sms_active_statuses(),true)||somsa_sms_slot_timestamp($b->slot)<=time()){$wpdb->update($queue,['status'=>'cancelled','updated_at'=>$now],['id'=>$job->id]);continue;}$r=somsa_sms_send_to($b->phone,somsa_sms_message($b));$wpdb->update($queue,['status'=>$r['state'],'provider_id'=>$r['provider_id']??null,'last_error'=>$r['error']??null,'updated_at'=>gmdate('Y-m-d H:i:s')],['id'=>$job->id]);}
 $events=$wpdb->prefix.'somsa_sms_notifications';$jobs=$wpdb->get_results($wpdb->prepare("SELECT * FROM $events WHERE status='queued' AND due_at<=%s ORDER BY due_at LIMIT 30",$now));foreach($jobs as $job){$claimed=$wpdb->query($wpdb->prepare("UPDATE $events SET status='sending',attempts=attempts+1,updated_at=%s WHERE id=%d AND status='queued'",$now,$job->id));if($claimed!==1)continue;$b=$wpdb->get_row($wpdb->prepare("SELECT * FROM $bookings WHERE id=%d",$job->booking_id));if(!$b||!in_array($b->status,somsa_sms_active_statuses(),true)||($job->event_type==='followup'&&somsa_sms_slot_timestamp($b->slot)>time())){$wpdb->update($events,['status'=>'cancelled','updated_at'=>$now],['id'=>$job->id]);continue;}$phone=$job->event_type==='owner'?get_option('somsa_sms_owner_phone',''):$b->phone;if(!$phone){$wpdb->update($events,['status'=>'cancelled','last_error'=>'recipient_not_configured','updated_at'=>gmdate('Y-m-d H:i:s')],['id'=>$job->id]);continue;}$r=somsa_sms_send_to($phone,somsa_sms_event_message($b,$job->event_type));$wpdb->update($events,['status'=>$r['state'],'provider_id'=>$r['provider_id']??null,'last_error'=>$r['error']??null,'updated_at'=>gmdate('Y-m-d H:i:s')],['id'=>$job->id]);}}
add_action('admin_menu',function(){add_submenu_page('somsa-studio','پیامک یادآوری','پیامک یادآوری','manage_options','somsa-sms','somsa_sms_admin');});
function somsa_sms_admin(){if(!current_user_can('manage_options'))return;if(isset($_POST['somsa_sms_save'])){check_admin_referer('somsa_sms_settings');$provider=sanitize_key($_POST['provider']??'');$sender=preg_replace('/[^0-9+]/','',sanitize_text_field(wp_unslash($_POST['sender']??'')));$owner=preg_replace('/[^0-9+]/','',sanitize_text_field(wp_unslash($_POST['owner_phone']??'')));$enabled=isset($_POST['enabled']);$username=trim(sanitize_text_field(wp_unslash($_POST['username']??'')));$password=trim((string)wp_unslash($_POST['password']??''));$oldPass=(string)get_option('somsa_sms_password','');if($enabled&&($provider!=='melipayamak'||$username===''||($password===''&&$oldPass==='')||!preg_match('/^[0-9+]{3,20}$/',$sender)||!preg_match('/^09\d{9}$/',$owner))){echo '<div class="notice notice-error"><p>برای فعال‌سازی، نام کاربری، رمز، شماره فرستنده و شماره ناخن‌کار را کامل کنید.</p></div>';}else{update_option('somsa_sms_provider',$provider==='melipayamak'?'melipayamak':'');update_option('somsa_sms_username',$username);update_option('somsa_sms_sender',$sender);update_option('somsa_sms_owner_phone',$owner);update_option('somsa_sms_enabled',$enabled?'1':'0');if($password!=='')update_option('somsa_sms_password',$password,false);echo '<div class="notice notice-success"><p>تنظیمات ذخیره شد. پیامک رزرو پس از پرداخت، یادآوری سه ساعت پیش از نوبت، و پیام پیگیری یک ماه پس از نوبت در صف ارسال قرار می‌گیرند.</p></div>';}}
 global $wpdb;$logs=$wpdb->get_results("SELECT q.*,b.customer,b.slot FROM {$wpdb->prefix}somsa_sms q LEFT JOIN {$wpdb->prefix}somsa_bookings b ON b.id=q.booking_id ORDER BY q.id DESC LIMIT 50");$events=$wpdb->get_results("SELECT q.*,b.customer,b.slot FROM {$wpdb->prefix}somsa_sms_notifications q LEFT JOIN {$wpdb->prefix}somsa_bookings b ON b.id=q.booking_id ORDER BY q.id DESC LIMIT 50");$states=['queued'=>'در صف','sending'=>'در حال ارسال','sent'=>'پذیرفته‌شده توسط سرویس','failed'=>'ردشده توسط سرویس','unknown'=>'نتیجه نامشخص؛ نیاز به پیگیری','cancelled'=>'لغوشده'];
 ?><div class="wrap" dir="rtl"><h1>پیامک SOMA STUDIO</h1><p>اطلاعات حساب ملی پیامک فقط در همین پنل ذخیره می‌شود؛ رمز را در گفت‌وگو نفرستید. هیچ پیام آزمایشی خودکاری ارسال نمی‌شود.</p><form method="post"><?php wp_nonce_field('somsa_sms_settings'); ?><table class="form-table"><tr><th>فعال‌سازی ارسال</th><td><label><input type="checkbox" name="enabled" <?php checked(get_option('somsa_sms_enabled','0'),'1'); ?>> ارسال واقعی پیامک</label></td></tr><tr><th>سامانه</th><td><select name="provider"><option value="melipayamak" <?php selected(get_option('somsa_sms_provider','melipayamak'),'melipayamak'); ?>>ملی پیامک</option></select></td></tr><tr><th>نام کاربری ملی پیامک</th><td><input name="username" class="regular-text" autocomplete="username" value="<?php echo esc_attr(get_option('somsa_sms_username','')); ?>"></td></tr><tr><th>رمز عبور وب‌سرویس</th><td><input type="password" name="password" autocomplete="new-password" class="regular-text" placeholder="<?php echo get_option('somsa_sms_password','')?'ذخیره شده؛ برای حفظ آن خالی بگذارید':'رمز وب‌سرویس ملی پیامک'; ?>"></td></tr><tr><th>شماره فرستنده</th><td><input name="sender" class="regular-text" inputmode="tel" value="<?php echo esc_attr(get_option('somsa_sms_sender','')); ?>"></td></tr><tr><th>شماره ناخن‌کار برای اعلان</th><td><input name="owner_phone" class="regular-text" inputmode="tel" placeholder="09xxxxxxxxx" value="<?php echo esc_attr(get_option('somsa_sms_owner_phone','')); ?>"></td></tr><tr><th>زمان یادآوری پیش از نوبت</th><td>۳ ساعت پیش از نوبت</td></tr><tr><th>پیگیری رزرو مجدد</th><td>یک ماه پس از زمان نوبت</td></tr></table><button class="button button-primary" name="somsa_sms_save">ذخیره تنظیمات</button></form><p>ارسال‌های زمان‌بندی‌شده به اجرای WP-Cron وابسته‌اند. برای اجرای دقیق روی هاست، wp-cron.php را از زمان‌بندی DirectAdmin هر ۵ دقیقه فراخوانی کنید.</p><h2>گزارش یادآوری سه‌ساعته</h2><table class="widefat striped"><thead><tr><th>رزرو</th><th>مشتری</th><th>نوبت</th><th>وضعیت</th><th>شناسه ارسال</th><th>خطا</th></tr></thead><tbody><?php foreach($logs as $r){echo '<tr>';foreach([$r->booking_id,$r->customer,$r->slot,$states[$r->status]??$r->status,$r->provider_id,$r->last_error] as $v)echo '<td>'.esc_html((string)$v).'</td>';echo '</tr>';}if(!$logs)echo '<tr><td colspan="6">هنوز پیامکی ثبت نشده است.</td></tr>'; ?></tbody></table><h2>پیام‌های رزرو و پیگیری ماهانه</h2><table class="widefat striped"><thead><tr><th>رزرو</th><th>مشتری</th><th>نوع</th><th>زمان نوبت</th><th>وضعیت</th><th>شناسه</th><th>خطا</th></tr></thead><tbody><?php foreach($events as $r){echo '<tr>';foreach([$r->booking_id,$r->customer,$r->event_type,$r->slot,$states[$r->status]??$r->status,$r->provider_id,$r->last_error] as $v)echo '<td>'.esc_html((string)$v).'</td>';echo '</tr>';}if(!$events)echo '<tr><td colspan="7">هنوز پیامی ثبت نشده است.</td></tr>'; ?></tbody></table></div><?php
}